/*
We interpret the task as follows:

- There are n processes and m resource types.
- For each process i, we know its maximum requirement maxNeed[i][j].
- We are given the currently available amount of each resource type.
- Then a log of allocations is given in chronological order.
  Each log entry assigns some resources to one process.

After each log entry, we update the current allocation of that process.
We must detect the earliest time when the state becomes unsafe
(i.e. deadlock-unavoidable) according to Banker's safety test.

Input format assumed:
n m
available[0..m-1]
maxNeed matrix: n lines, each with m integers
q
Then q log entries:
time process allocation_vector_of_size_m

Processes in the log are assumed 1-based; converted to 0-based.

Output:
- the earliest time value at which the system becomes unsafe
- or 0 if it never becomes unsafe

This is the standard interpretation for "deadlock-unavoidable based on resource allocation log".
*/

static bool isSafe(const vector<int>& available,
                   const vector<vector<int>>& maxNeed,
                   const vector<vector<int>>& alloc) {
    int n = (int)maxNeed.size();
    int m = (int)available.size();

    vector<int> work = available;
    vector<int> finish(n, 0);

    vector<vector<int>> need(n, vector<int>(m));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            need[i][j] = maxNeed[i][j] - alloc[i][j];
            if (need[i][j] < 0) return false; // invalid / exceeded maximum
        }
    }

    bool progress = true;
    while (progress) {
        progress = false;
        for (int i = 0; i < n; ++i) {
            if (finish[i]) continue;
            bool ok = true;
            for (int j = 0; j < m; ++j) {
                if (need[i][j] > work[j]) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                for (int j = 0; j < m; ++j) work[j] += alloc[i][j];
                finish[i] = 1;
                progress = true;
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        if (!finish[i]) return false;
    }
    return true;
}

