public class DeadlockDetector {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt(); // number of processes
        int m = sc.nextInt(); // number of resource types

        int[] available = new int[m];
        for (int i = 0; i < m; i++) {
            available[i] = sc.nextInt();
        }

        int[][] max = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                max[i][j] = sc.nextInt();
            }
        }

        int[][] allocation = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                allocation[i][j] = sc.nextInt();
            }
        }

        int t = sc.nextInt(); // number of log entries
        int[][] logs = new int[t][3]; // time, process, resource type
        for (int i = 0; i < t; i++) {
            logs[i][0] = sc.nextInt();
            logs[i][1] = sc.nextInt();
            logs[i][2] = sc.nextInt();
        }

        // Calculate need matrix
        int[][] need = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                need[i][j] = max[i][j] - allocation[i][j];
            }
        }

        // Simulate resource allocation over time
        for (int[] log : logs) {
            int time = log[0];
            int proc = log[1];
            int resType = log[2];

            // Allocate one unit of resType to proc
            available[resType]--;
            allocation[proc][resType]++;
            need[proc][resType]--;

            // Check if system is in a safe state
            if (!isSafeState(available, allocation, need, n, m)) {
                System.out.println(time);
                return;
            }
        }

        System.out.println("No deadlock unavoidable state reached");
    }

    private static boolean isSafeState(int[] available, int[][] allocation, int[][] need, int n, int m) {
        int[] work = available.clone();
        boolean[] finish = new boolean[n];

        for (int count = 0; count < n; count++) {
            boolean found = false;
            for (int i = 0; i < n; i++) {
                if (!finish[i]) {
                    boolean canProceed = true;
                    for (int j = 0; j < m; j++) {
                        if (need[i][j] > work[j]) {
                            canProceed = false;
                            break;
                        }
                    }
                    if (canProceed) {
                        for (int j = 0; j < m; j++) {
                            work[j] += allocation[i][j];
                        }
                        finish[i] = true;
                        found = true;
                    }
                }
            }
            if (!found) break;
        }

        for (boolean f : finish) {
            if (!f) return false;
        }
        return true;
    }
}

