/*
 * Deadlock Detection
 *
 * We are given:
 * - p processes, r resources
 * - for each process: the set of resources it may need
 * - a log of allocation events (time, process, resource)
 *
 * At any time t, consider only log entries with time <= t.
 * A process can finish iff all resources it requires have been allocated to it.
 * Finished processes release all resources they hold, which may allow others to finish.
 *
 * We must find the earliest time when the state becomes deadlock-unavoidable:
 * i.e. after processing all events at that time, not all processes can be completed.
 *
 * Input format assumed by this solution:
 * p r
 * For i = 1..p:
 *   k ri1 ri2 ... rik
 * m
 * For j = 1..m:
 *   time process resource
 *
 * Resources and processes may be given as strings.
 *
 * If deadlock never becomes unavoidable, print "ok".
 *
 * This is the standard simulation:
 * - sort events by time
 * - after each time batch, build current holdings
 * - run reduction:
 *      repeatedly finish any unfinished process whose required resources are all currently available to it
 *      when finishing, release all held resources
 * - if some process remains unfinished, report current time
 */
public class Main {
    static class Event {
        int time;
        int p;
        int r;
        Event(int time, int p, int r) {
            this.time = time;
            this.p = p;
            this.r = r;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        Integer PObj = fs.nextIntNullable();
        if (PObj == null) return;
        int P = PObj;
        int R = fs.nextInt();

        Map<String, Integer> procId = new HashMap<>();
        Map<String, Integer> resId = new HashMap<>();

        List<Set<Integer>> need = new ArrayList<>();
        for (int i = 0; i < P; i++) need.add(new HashSet<>());

        for (int i = 0; i < P; i++) {
            String pname = fs.next();
            procId.put(pname, i);

            int k = fs.nextInt();
            for (int j = 0; j < k; j++) {
                String rname = fs.next();
                int rid = resId.computeIfAbsent(rname, z -> resId.size());
                need.get(i).add(rid);
            }
        }

        int M = fs.nextInt();
        List<Event> events = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            int t = fs.nextInt();
            String pname = fs.next();
            String rname = fs.next();

            Integer pid = procId.get(pname);
            if (pid == null) {
                pid = procId.size();
                procId.put(pname, pid);
                while (need.size() <= pid) need.add(new HashSet<>());
            }
            int rid = resId.computeIfAbsent(rname, z -> resId.size());
            events.add(new Event(t, pid, rid));
        }

        events.sort(Comparator.comparingInt(e -> e.time));

        int totalP = need.size();
        List<Set<Integer>> held = new ArrayList<>();
        for (int i = 0; i < totalP; i++) held.add(new HashSet<>());

        int idx = 0;
        while (idx < events.size()) {
            int t = events.get(idx).time;
            while (idx < events.size() && events.get(idx).time == t) {
                Event e = events.get(idx++);
                while (held.size() <= e.p) held.add(new HashSet<>());
                held.get(e.p).add(e.r);
            }

            if (!canAllFinish(need, held)) {
                System.out.println(t);
                return;
            }
        }

        System.out.println("ok");
    }

    static boolean canAllFinish(List<Set<Integer>> need, List<Set<Integer>> heldOrig) {
        int n = need.size();

        List<Set<Integer>> held = new ArrayList<>(n);
        for (int i = 0; i < n; i++) held.add(new HashSet<>(i < heldOrig.size() ? heldOrig.get(i) : Collections.emptySet()));

        boolean[] done = new boolean[n];
        boolean progress = true;

        while (progress) {
            progress = false;
            for (int i = 0; i < n; i++) {
                if (done[i]) continue;
                if (held.get(i).containsAll(need.get(i))) {
                    done[i] = true;
                    progress = true;

                    Set<Integer> released = held.get(i);
                    if (!released.isEmpty()) {
                        for (int j = 0; j < n; j++) {
                            if (!done[j] && j != i) {
                                held.get(j).addAll(released);
                            }
                        }
                    }
                }
            }
        }

        for (boolean b : done) {
            if (!b) return false;
        }
        return true;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;

            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        Integer nextIntNullable() throws IOException {
            String s = next();
            if (s == null) return null;
            return Integer.parseInt(s);
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
